  // Distribute savings to a goal — creates an income tx tagged with goal_id
  // and increases the goal's saved amount.
  async function distributeSavings(goalId: string, amount: number) {
    const goal = goals.find((g) => g.id === goalId);
    if (!goal || amount <= 0) return;
    const today = new Date().toISOString().slice(0, 10);
    const newTx: Transaction = {
      id: crypto.randomUUID(),
      type: "income",
      amount,
      category_id: null,
      source: "Накопления",
      date: today,
      comment: `В цель: ${goal.name}`,
      payment_method: "debit",
      card_id: null,
      goal_id: goalId,
      created_at: new Date().toISOString(),
    };
    await putTransaction(newTx);
    await putGoal({ ...goal, saved: goal.saved + amount });
    await refresh();
  }

  // Repay credit card debt — creates an income tx tagged with card_id
  // (reduces card debt) and a corresponding expense from debit balance.
  async function repayCard(cardId: string, amount: number, dueDate?: string | null) {
    if (amount <= 0) return;
    const today = new Date().toISOString().slice(0, 10);
    const card = cards.find((c) => c.id === cardId);
    if (!card) return;

    try {
      // 1. Собираем активные расходы кредитки с дедлайнами от старых к новым
      const cardTx = transactions.filter(
        (t) => t.card_id === cardId && t.type === "expense" && t.credit_due_date
      ).sort((a, b) => 
        new Date(a.credit_due_date || "").getTime() - 
        new Date(b.credit_due_date || "").getTime()
      );

      if (dueDate) {
        // ВАРИАНТ А: Выбран конкретный период — гасим его полностью
        const txsToUpdate = cardTx.filter((t: any) => (t.creditDueDate || t.credit_due_date) === dueDate);
        for (const originalTx of txsToUpdate) {
          const updatedTx = {
            ...originalTx,
            credit_due_date: null,
            creditDueDate: null,
            card_id: originalTx.card_id || (originalTx as any).cardId,
            category_id: originalTx.category_id || (originalTx as any).categoryId
          };
          await putTransaction(updatedTx);
        }
      } else {
        // ВАРИАНТ Б: Произвольная сумма — гасим покупки ЦЕЛИКОМ, на сколько хватает денег
        let remainingRepay = amount;

        for (const tx of cardTx) {
          if (remainingRepay <= 0) break;

          // Гасим дедлайн только если внесенных денег хватает, чтобы ПОЛНОСТЬЮ закрыть эту покупку
          if (remainingRepay >= tx.amount) {
            remainingRepay -= tx.amount;
            const updatedTx = {
              ...tx,
              credit_due_date: null,
              creditDueDate: null,
              card_id: tx.card_id || (tx as any).cardId,
              category_id: tx.category_id || (tx as any).categoryId
            };
            await putTransaction(updatedTx);
          } else {
            // Если на покупку целиком денег не хватило — мы её вообще не трогаем!
            // Она останется висеть в модалке со своим дедлайном, пока ты её не закроешь.
            break; 
          }
        }
      }

      // 2. Создаем стандартный чек пополнения кредитки для баланса счета
      const repayTx: Transaction = {
        id: crypto.randomUUID(),
        type: "income",
        amount,
        category_id: null,
        source: `Погашение долга: ${card.name}`,
        date: today,
        comment: dueDate ? `Погашение периода до ${dueDate.split("-").reverse().join(".")}` : "Произвольное пополнение карты",
        payment_method: "card",
        card_id: cardId,
        created_at: new Date().toISOString(),
      };

      await putTransaction(repayTx);
      await refresh();
    } catch (e) {
      console.error("Ошибка при обработке платежа по кредитке:", e);
    }
  }

